public class SafeDivideTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("divide(10, 2)", java.util.Optional.of(5), SafeDivide.divide(10, 2));
        check("divide(10, 4) uses integer division", java.util.Optional.of(2), SafeDivide.divide(10, 4));
        check("divide(-9, 3)", java.util.Optional.of(-3), SafeDivide.divide(-9, 3));
        try {
            check("divide by zero -> empty", java.util.Optional.empty(), SafeDivide.divide(7, 0));
        } catch (RuntimeException e) {
            System.out.println("FAIL  divide by zero -> empty -- threw " + e.getClass().getSimpleName());
            failures++;
        }

        check("divideOr(8, 2, 99)", 4, SafeDivide.divideOr(8, 2, 99));
        try {
            check("divideOr falls back on zero divisor", 42, SafeDivide.divideOr(5, 0, 42));
        } catch (RuntimeException e) {
            System.out.println("FAIL  divideOr falls back on zero divisor -- threw " + e.getClass().getSimpleName());
            failures++;
        }
        check("divideOr(0, 5, 7) -> real quotient 0", 0, SafeDivide.divideOr(0, 5, 7));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

